int num = 9045;
int s = 0;
while (num > 0)
{
    s += num % 10;
    num /= 10;
}
Console.WriteLine(s);

int sum = 0;
int x = int.Parse(Console.ReadLine());
while (x != -1)
{
    sum += x;
    x = int.Parse(Console.ReadLine());
}
Console.WriteLine(sum);

int k = 100;
int c = 0;
while (k > 1)
{
    k /= 2;
    c++;
}
Console.WriteLine(c);

int n = 123;
int r = 0;
while (n > 0)
{
    r = r * 10 + n % 10;
    n /= 10;
}
Console.WriteLine(r);
